export const LEGACY_MODULE_VARS_SUMMARY = {
  modules: 366,
  variables: 1621,
  withheld: 20
} as const;

/**
 * Reads one module variable the way the original's
 * `eval(import_module('x'))` prologue does.
 *
 * Returns null for a name the module does not define, matching PHP's
 * undefined-variable read rather than throwing.
 */
export function legacyModuleVar(module: string, name: string): PhpValue {
  return LEGACY_MODULE_VARS[module]?.[name] ?? null;
}
